def match_parens(lst):
    s, t = lst[0], lst[1]
    total_open = s.count('(') + t.count('(')
    total_close = s.count(')') + t.count(')')
    if total_open != total_close:
        return 'No'
    # Check s + t
    balance = 0
    for c in s + t:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            break
    if balance == 0:
        return 'Yes'
    # Check t + s
    balance = 0
    for c in t + s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            break
    if balance == 0:
        return 'Yes'
    return 'No'
